orig_units_path = root / 'Dota2 原版游戏配置/npc_units.txt'


def strip_comment(line: str) -> str:
    in_q = False
    i = 0
    while i < len(line):
        ch = line[i]
        if ch == '"':
            in_q = not in_q
        if not in_q and ch == '/' and i + 1 < len(line) and line[i+1] == '/':
            return line[:i]
        i += 1
    return line


def parse_unit_blocks(path: Path):
    text = path.read_text(encoding='utf-8', errors='ignore').splitlines()
    depth = 0
    pending_key = None
    current_unit = None
    current_depth = None
    unit_data = {}
    unit_order = []

    key_value_re = re.compile(r'^\s*"([^"]+)"\s+"([^"]*)"')
    key_only_re = re.compile(r'^\s*"([^"]+)"\s*$')

    for raw in text:
        line = strip_comment(raw).strip()
        if not line:
            continue

        m = key_value_re.match(line)
        if m:
            k, v = m.group(1), m.group(2)
            if current_unit is not None and depth == current_depth:
                unit_data[current_unit][k] = v
            pending_key = None
            continue

        m = key_only_re.match(line)
        if m:
            pending_key = m.group(1)
            continue

        if line.startswith('{'):
            new_depth = depth + 1
            if pending_key is not None:
                if depth == 1 and pending_key != 'Version':
                    current_unit = pending_key
                    current_depth = new_depth
                    unit_data[current_unit] = {}
                    unit_order.append(current_unit)
            depth = new_depth
            pending_key = None
            continue

        if line.startswith('}'):
            if current_unit is not None and depth == current_depth:
                current_unit = None
                current_depth = None
            depth -= 1
            if depth < 0:
                depth = 0
            pending_key = None
            continue

    return unit_data, unit_order


def norm_model(s: str):
    return s.replace('\\\\', '/').replace('\\', '/').lower().strip()

custom_units, _ = parse_unit_blocks(custom_units_path)
orig_units, orig_order = parse_unit_blocks(orig_units_path)

orig_model_speed = {}
orig_model_speed_multi = {}
orig_unit_speed = {}

for uname in orig_order:
    data = orig_units.get(uname, {})
    ms = data.get('MovementSpeed')
    if ms is not None:
        try:
            orig_unit_speed[uname] = int(float(ms))
        except ValueError:
            pass
    model = data.get('Model')
    if model and ms is not None:
        try:
            ms_i = int(float(ms))
        except ValueError:
            continue
        key = norm_model(model)
        if key not in orig_model_speed:
            orig_model_speed[key] = ms_i
            orig_model_speed_multi[key] = {ms_i}
        else:
            orig_model_speed_multi[key].add(ms_i)

for k, vals in list(orig_model_speed_multi.items()):
    if len(vals) > 1:
        preferred = [v for v in vals if v not in (0,)]
        if preferred:
            orig_model_speed[k] = sorted(preferred)[0]
        else:
            orig_model_speed[k] = sorted(vals)[0]

monster_text = monster_path.read_text(encoding='utf-8', errors='ignore')
block_re = re.compile(r'(\t"([^"]+)"\s*\{\n)(.*?)(\t\}\n?)', re.S)
unit_line_re = re.compile(r'^(\s*"UnitName"\s+"([^"]+)"\s*)$', re.M)
move_line_re = re.compile(r'^(\s*"MovementSpeed"\s+"([^"]+)"\s*)$', re.M)

stats = {
    'total': 0,
    'updated': 0,
    'inserted': 0,
    'replaced': 0,
    'missing_custom_unit': [],
    'missing_model': [],
    'missing_orig_speed': [],
}


def resolve_speed_for_unit(unit_name: str):
    c = custom_units.get(unit_name)
    if not c:
        return None, 'missing_custom_unit'
    model = c.get('Model')
    if not model:
        return None, 'missing_model'
    mkey = norm_model(model)
    if mkey in orig_model_speed:
        return orig_model_speed[mkey], None
    if unit_name in orig_unit_speed:
        return orig_unit_speed[unit_name], None
    return None, ('missing_orig_speed', model)


def repl(m):
    head, tpl, body, tail = m.group(1), m.group(2), m.group(3), m.group(4)
    stats['total'] += 1
    um = unit_line_re.search(body)
    if not um:
        return m.group(0)
    unit_name = um.group(2)
    speed, err = resolve_speed_for_unit(unit_name)
    if speed is None:
        if err == 'missing_custom_unit':
            stats['missing_custom_unit'].append((tpl, unit_name))
        elif err == 'missing_model':
            stats['missing_model'].append((tpl, unit_name))
        else:
            stats['missing_orig_speed'].append((tpl, unit_name, err[1]))
        return m.group(0)

    mv = move_line_re.search(body)
