        new_body = move_line_re.sub(lambda mm: f'{mm.group(1).split("\"")[0]}"MovementSpeed" "{speed}"', body, count=1)
        if new_body != body:
            stats['updated'] += 1
            stats['replaced'] += 1
        return head + new_body + tail

    insert_at = um.end(1)
    new_body = body[:insert_at] + f'\n\t\t"MovementSpeed" "{speed}"' + body[insert_at:]
    stats['updated'] += 1
    stats['inserted'] += 1
    return head + new_body + tail

new_text = block_re.sub(repl, monster_text)
monster_path.write_text(new_text, encoding='utf-8', newline='\n')

print('total_blocks', stats['total'])
